import { ChangeDetectionStrategy, Component } from '@angular/core';
import { CompanyService } from '../../services/company-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule, FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-edit-company',
  imports: [CommonModule, ReactiveFormsModule, ],
  templateUrl: './edit-company.html',
  styleUrl: './edit-company.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EditCompany {
companyForm! : FormGroup;
companyId! : number;
isLoading = true;

constructor(
    private fb: FormBuilder,
    private service: CompanyService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

    ngOnInit(): void {
    this.companyForm = this.fb.group({
      companyName: ['', Validators.required],
      gstin: ['', Validators.required],
      companyAddress: ['', Validators.required],
      accNo: ['', Validators.required],
      bankName: ['', Validators.required],
      branchName: ['', Validators.required],
      ifsc: ['', Validators.required],
      phone: ['', Validators.required],
    });
   const id = Number(this.route.snapshot.paramMap.get('id'));
    if (id) {
      this.companyId = id;
      this.service.getCompanyByID(id).subscribe(company => {
        this.companyForm.patchValue(company); 
        this.isLoading = false;
      });
    } else {
      this.isLoading = false;
    }
    }
    onCancel(){
    this.resetForm();
    this.router.navigate(['/company-master']);
  }
   onSubmit() {
  if (this.companyForm.invalid) 
    return;

   const dto = {
    ...this.companyForm.value,
   }

  console.log("Submitting Company:", dto);

  this.service.updateCompany(this.companyId, dto).subscribe({
    next: () => {
      alert('✅ Company updated successfully');
      this.resetForm();
    },
    error: (err) => {
      console.error('❌ Upload failed', err);
      alert(err.error?.message || 'Upload failed. Please try again.');
    }
  });

  this.router.navigate(['/company-master'])
}


  private resetForm() {
    this.companyForm.reset();
  }
  }
